`UPDATE tool_calls SET input=${value('preview')},input_bytes=${value('bytes')},input_blob_key=NULL,
      input_bundle_id=(SELECT id FROM archive_bundles WHERE project_id=? AND archive_key=?),input_bundle_entry=${value('entry')}
      WHERE ${identity}`

`CREATE TRIGGER IF NOT EXISTS events_raw_credential AFTER INSERT ON events WHEN NEW.raw_revision IS NULL BEGIN
     INSERT INTO raw_credentials (token_id, owner_member_id, provenance)
       VALUES (NEW.token_id, ${rawCredentialOwner('NEW.token_id')}, ${rawCredentialProvenance('NEW.token_id')}) ON CONFLICT DO NOTHING;
     UPDATE raw_provenance_state SET revision = revision + 1 WHERE id = 1;
     UPDATE events SET raw_revision = (SELECT revision FROM raw_provenance_state WHERE id = 1)
       WHERE project_id = NEW.project_id AND event_id = NEW.event_id; END`

`INSERT INTO events (${rawMaterial.insert.columns.join(',')})
      SELECT ${rawMaterial.insert.sql} WHERE ${admission.map((a) => a.sql).join(' AND ')}
      ON CONFLICT(project_id,event_id) DO NOTHING`

`INSERT INTO attachments (${merged.insert.columns.join(',')})
          SELECT ${merged.insert.sql} ${merged.insert.source!.sql} AND ${RAW_ROW_GATE}
          ON CONFLICT (project_id, attachment_id) DO NOTHING`

`INSERT INTO plans (${merged.insert.columns.join(', ')})
        SELECT ${merged.insert.sql} WHERE ${RAW_ROW_GATE}
        ON CONFLICT(project_id,plan_key) DO UPDATE SET ${merged.update.sql}`

`UPDATE tool_calls AS t SET ${mutation.update.sql}
      WHERE t.project_id = ? AND t.tool_call_id = ? AND t.session_id = ? AND ${gate.sql}
        AND ${changed.sql}
      RETURNING tool_call_id`
